      "id": "projects_teste_alfredo_22_RESEARCH_sistema-para-controlar-rotina-de-criancas-autiostas-nivel-1_knowledge_05-autenticacao-autorizacao_md",
      "path": "projects/teste_alfredo_22/RESEARCH/sistema-para-controlar-rotina-de-criancas-autiostas-nivel-1/knowledge/05-autenticacao-autorizacao.md",
